insert into public.destinations (id, slug, name, region, lat, lng, summary, best_time, getting_there, faq, hero_image, sw) values
  ('a1000000-0000-4000-8000-000000000001', 'naivasha', 'Naivasha', 'Nakuru County', -0.7167, 36.4333, 'A freshwater lake in the Rift Valley with hippos, boat rides, Hell''s Gate cycling and lakeside lodges.', 'All year. Driest from June to October and January to February.', 'About 2 hours (90 km) from Nairobi by road on the Nairobi-Nakuru highway.', '[{"q":"Can I do Naivasha as a day trip?","a":"Yes. Leave Nairobi by 7am and you can cycle Hell''s Gate, take a boat ride and be back by evening."},{"q":"Is the boat ride safe with hippos around?","a":"Licensed boat operators keep a safe distance and provide life jackets."}]'::jsonb, 'naivasha-lake', '{"summary":"Ziwa la maji baridi katika Bonde la Ufa lenye viboko, safari za mashua, baiskeli Hell''s Gate na hoteli kando ya ziwa.","bestTime":"Mwaka mzima. Kiangazi ni Juni hadi Oktoba na Januari hadi Februari.","gettingThere":"Takriban saa 2 (km 90) kutoka Nairobi kwa barabara kuu ya Nairobi-Nakuru."}'::jsonb),
  ('a1000000-0000-4000-8000-000000000002', 'maasai-mara', 'Maasai Mara', 'Narok County', -1.4902, 35.1435, 'Open savanna, big cats and, from July to October, the wildebeest migration.', 'July to October for the migration; good game viewing all year.', '5 to 6 hours (about 270 km) by road via Narok, or a 45-minute flight from Wilson Airport.', '[{"q":"Do Kenyan citizens pay less park fees?","a":"Yes. Citizen and resident rates are much lower than non-resident rates. Bring your ID."},{"q":"Is the road to the Mara rough?","a":"The last stretch can be bumpy, especially in the rains. Our vans are 4x4."}]'::jsonb, 'maasai-mara-savanna', '{"summary":"Nyika pana, wanyama wakubwa na, kuanzia Julai hadi Oktoba, uhamaji wa nyumbu.","bestTime":"Julai hadi Oktoba kwa uhamaji; wanyama huonekana mwaka mzima.","gettingThere":"Saa 5 hadi 6 (takriban km 270) kwa barabara kupitia Narok, au dakika 45 kwa ndege kutoka Wilson."}'::jsonb),
  ('a1000000-0000-4000-8000-000000000003', 'diani', 'Diani', 'Kwale County', -4.2799, 39.5947, 'White sand, warm Indian Ocean water, snorkelling at Kisite and colobus monkeys in the coastal forest.', 'December to March and July to October. April to June is the long rains.', 'SGR train from Nairobi Terminus to Mombasa (about 5 hours), then about 1.5 hours by road via the Likoni ferry.', '[{"q":"Which SGR class is included?","a":"Each package says Economy or First Class. Bring your ID; tickets are booked in your name."},{"q":"When is the best snorkelling?","a":"Calm mornings from October to March usually have the clearest water."}]'::jsonb, 'diani-boat', '{"summary":"Mchanga mweupe, maji ya joto ya Bahari Hindi, kupiga mbizi Kisite na tumbili aina ya mbega msituni.","bestTime":"Desemba hadi Machi na Julai hadi Oktoba. Aprili hadi Juni ni masika.","gettingThere":"Treni ya SGR kutoka Nairobi hadi Mombasa (takriban saa 5), kisha saa 1.5 kwa barabara kupitia kivuko cha Likoni."}'::jsonb),
  ('a1000000-0000-4000-8000-000000000004', 'amboseli', 'Amboseli', 'Kajiado County', -2.6527, 37.2606, 'Big elephant herds under Mount Kilimanjaro, swamps full of birds and wide open plains.', 'June to October and January to February, when Kilimanjaro is often clear in the early morning.', 'About 4 hours (240 km) by road via Emali or Namanga.', '[{"q":"Will I see Kilimanjaro?","a":"Usually at sunrise and sunset. Clouds often cover it in the middle of the day."}]'::jsonb, 'amboseli-kilimanjaro', '{"summary":"Makundi makubwa ya tembo chini ya Mlima Kilimanjaro, vinamasi vyenye ndege na nyanda pana.","bestTime":"Juni hadi Oktoba na Januari hadi Februari, Kilimanjaro huonekana vizuri asubuhi.","gettingThere":"Takriban saa 4 (km 240) kwa barabara kupitia Emali au Namanga."}'::jsonb);
