insert into public.packages (id, agency_id, destination_id, slug, title, summary, nights, margin_bps, deposit_pct, instalments, final_due_days, inclusions, exclusions, hero_image, from_price_kes, status, published_at) values
  ('a5000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'naivasha-day-escape', 'Naivasha day escape: Hell''s Gate and the lake', 'Cycle Hell''s Gate in the morning, lunch by the lake, then a boat ride to Crescent Island.', 0, 1500, 100, 0, 7, array['Return shuttle from Nairobi', 'Bike and guide', 'Lunch', 'Boat ride'], array['Park entry fees', 'Drinks'], 'naivasha-lake', 8100, 'published', now()),
  ('a5000000-0000-4000-8000-000000000002', 'a2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'naivasha-lakeside-weekend', 'Naivasha lakeside weekend', 'Two nights in a lake-view room with breakfast, return shuttle and a boat ride to see the hippos.', 2, 1500, 25, 3, 7, array['Return shuttle from Nairobi', '2 nights, breakfast', 'Boat ride'], array['Lunch and dinner', 'Drinks'], 'naivasha-lake', 15700, 'published', now()),
  ('a5000000-0000-4000-8000-000000000003', 'a2000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'naivasha-camping-weekend', 'Naivasha camping weekend with Hell''s Gate cycling', 'Two nights in a furnished tent by the lake and a guided cycle through Hell''s Gate gorge.', 2, 1500, 25, 2, 7, array['Return shuttle from Nairobi', '2 nights in a furnished tent', 'Bike and guide'], array['Meals', 'Park entry fees'], 'naivasha-lake', 9700, 'published', now()),
